// Parse DrChrono ERA/835 denied line items into individual items for processing
const response = $input.first().json;
const results = response.results || response.data || [];

if (!results.length) {
  // No new denials found — exit gracefully
  return [{ json: { no_denials: true } }];
}

// Map each denied line item to our normalized format
return results.map(item => ({
  json: {
    source: 'drchrono_era',
    needs_classification: true,
    raw_input: JSON.stringify(item),
    era_data: {
      line_item_id: item.id || '',
      patient_name: (item.patient_first_name || '') + ' ' + (item.patient_last_name || ''),
      dos: item.service_date || '',
      denied_amount: parseFloat(item.billed_amount || item.balance || 0),
      denial_code: item.denial_reason || item.adjustment_reason_code || '',
      claim_number: item.claim_id || item.claim_number || '',
      cpt_codes: item.procedure_code ? [item.procedure_code] : [],
      provider: item.rendering_provider || item.billing_provider || '',
      npi: item.provider_npi || '',
      payer_name: item.insurance_name || item.payer_name || '',
      member_id: item.member_id || item.insurance_id || '',
      denial_date: item.posted_date || item.service_date || new Date().toISOString().split('T')[0]
    }
  }
}));

// Prepare scanned denial for Gemini multimodal classification
const binaryData = $input.first().binary?.data;
const fileMetadata = $('Google Drive — Watch Denial Inbox').first().json;

if (!binaryData) {
  throw new Error('No binary data found — file download may have failed');
}

const base64Content = binaryData.data;
const mimeType = binaryData.mimeType || fileMetadata.mimeType || 'application/pdf';
const fileName = fileMetadata.name || 'unknown_scan';

// Validate mime type
const allowedTypes = ['application/pdf', 'image/png', 'image/jpeg', 'image/tiff', 'image/webp'];
if (!allowedTypes.includes(mimeType)) {
  return [{
    json: {
      parse_failed: true,
      file_id: fileMetadata.id,
      file_name: fileName,
      error: `Unsupported file type: ${mimeType}. Accepted: PDF, PNG, JPEG, TIFF, WEBP`
    }
  }];
}

// Build Gemini multimodal request with inline image/PDF
const systemPrompt = `SYSTEM PROMPT — Denial Classification Agent (Multimodal/Scan)

You are a medical billing denial classification specialist for practices operating under the Prestige Health & Wellness (PHW) umbrella. PHW has 10 independent entities that each operate under their own legal name (e.g., FIDI Chiropractic PC). Denials are addressed to the specific entity, NOT to "Prestige Health & Wellness."

YOUR TASK:
Analyze the scanned denial letter image/PDF provided and:
1. Extract the ENTITY NAME the denial is addressed to (the practice name on the letter)
2. Extract the PAYER NAME (insurance company sending the denial)
3. Classify the denial reason into one of the known codes if possible
4. Extract all structured data for pipeline processing

KNOWN DENIAL CODES (Optum/UHC specific — may not apply to other payers):
1. PTOT08A — Maximum Therapy Benefit (MTB) Reached
2. PTOT05 — Non-Skilled Services
3. PTOT21 — Re-Evaluation Bundled
4. PTOT19 — Duplicate Evaluation

IMPORTANT: If the payer is NOT Optum/UnitedHealthcare, or if the denial reason does not match the 4 known codes above, still extract all data fields but set denial_code to "OTHER" and provide the raw denial reason text in denial_label.

OUTPUT FORMAT (strict JSON):
{
  "classification": {
    "denial_code": "PTOT08A | PTOT05 | PTOT21 | PTOT19 | OTHER",
    "denial_label": "human-readable label or raw denial reason text",
    "confidence": 0.0-1.0,
    "reasoning": "brief explanation",
    "keywords_matched": []
  },
  "entity": {
    "name_on_denial": "exact practice name as shown on the denial letter",
    "address_on_denial": "practice address from the letter if visible"
  },
  "patient": {
    "name": "First Last",
    "dob": "YYYY-MM-DD",
    "member_id": "string"
  },
  "claim": {
    "claim_number": "string",
    "dos_start": "YYYY-MM-DD",
    "dos_end": "YYYY-MM-DD",
    "cpt_codes": [],
    "denied_amount": 0.00,
    "denial_date": "YYYY-MM-DD"
  },
  "payer": {
    "name": "exact payer name from the letter",
    "plan_type": "Fully Insured | Self-Funded (ERISA) | Unknown"
  },
  "provider": {
    "name": "treating provider name",
    "npi": "NPI if visible"
  },
  "filing_deadline": "YYYY-MM-DD",
  "urgency": "standard | urgent",
  "missing_fields": [],
  "scan_quality": "good | fair | poor"
}

RULES:
- Extract the EXACT entity/practice name as printed on the denial letter
- Extract the EXACT payer name — do NOT assume Optum/UHC
- If denial code is not one of the 4 known codes, set to "OTHER" with the raw reason in denial_label
- If confidence < 70%, set denial_code to "OTHER"
- Calculate filing_deadline as denial_date + 365 days
- Do NOT hallucinate — if a field is not visible, add to missing_fields
- Report scan_quality based on legibility`;

const requestBody = {
  contents: [{
    role: 'user',
    parts: [
      { text: systemPrompt },
      {
        inline_data: {
          mime_type: mimeType,
          data: base64Content
        }
      }
    ]
  }],
  generationConfig: {
    maxOutputTokens: 4096,
    temperature: 0.1
  }
};

return [{
  json: {
    request_body: JSON.stringify(requestBody),
    file_id: fileMetadata.id,
    file_name: fileName,
    mime_type: mimeType,
    source: 'gdrive_scan'
  }
}];

// Parse Gemini multimodal classification response
const response = $input.first().json;
const scanMeta = $('Prepare Multimodal Request').first().json;

let text = '';
if (response.candidates && response.candidates[0]) {
  const parts = response.candidates[0].content?.parts || [];
  text = parts.map(p => p.text || '').join('');
}

// Strip markdown code fences
text = text.trim();
if (text.startsWith('```')) text = text.split('\n').slice(1).join('\n');
if (text.endsWith('```')) text = text.slice(0, text.lastIndexOf('```'));
text = text.trim();
if (text.startsWith('json')) text = text.slice(4).trim();

let classification;
try {
  classification = JSON.parse(text);
} catch (e) {
  return [{
    json: {
      parse_failed: true,
      file_id: scanMeta.file_id,
      file_name: scanMeta.file_name,
      error: `Failed to parse Gemini response: ${e.message}`,
      raw_response: text.slice(0, 500)
    }
  }];
}

const c = classification.classification || {};
const entity = classification.entity || {};
const patient = classification.patient || {};
const claim = classification.claim || {};
const payer = classification.payer || {};
const provider = classification.provider || {};

// Check if Gemini could parse the document at all
if (!patient.name && !claim.claim_number && !claim.dos_start) {
  return [{
    json: {
      parse_failed: true,
      file_id: scanMeta.file_id,
      file_name: scanMeta.file_name,
      error: 'Gemini could not extract any meaningful data from the scanned document',
      scan_quality: classification.scan_quality || 'poor'
    }
  }];
}

const denialDate = claim.denial_date || new Date().toISOString().split('T')[0];
const deadline = new Date(denialDate);
deadline.setDate(deadline.getDate() + 365);

return [{
  json: {
    parse_failed: false,
    denial_code: c.denial_code || 'OTHER',
    denial_label: c.denial_label || 'Unknown',
    confidence: c.confidence || 0,
    reasoning: c.reasoning || '',
    entity_name_on_denial: entity.name_on_denial || '',
    entity_address_on_denial: entity.address_on_denial || '',
    patient_name: patient.name || 'Unknown Patient',
    member_id: patient.member_id || '',
    dos: claim.dos_start || '',
    denied_amount: parseFloat(claim.denied_amount) || 0,
    denial_date: denialDate,
    filing_deadline: deadline.toISOString().split('T')[0],
    plan_type: payer.plan_type || 'Unknown',
    payer_name: payer.name || 'Unknown',
    claim_number: claim.claim_number || '',
    provider: provider.name || '',
    npi: provider.npi || '',
    cpt_codes: claim.cpt_codes || [],
    missing_fields: classification.missing_fields || [],
    scan_quality: classification.scan_quality || 'unknown',
    urgency: classification.urgency || 'standard',
    source: 'gdrive_scan',
    file_id: scanMeta.file_id,
    file_name: scanMeta.file_name
  }
}];

// Forward scan classification data to the shared pipeline
// (Google Drive Move node returns Drive API response, not our data)
const classData = $('Parse Scan Classification').first().json;
return [{ json: classData }];

// Parse manual fallback entry (used when scan fails or for direct API integration)
const input = $input.first().json;

let needsClassification = true;
let parsedData = {};

if (input.denial_code && input.patient_name && input.dos && input.denied_amount) {
  needsClassification = false;
  parsedData = {
    denial_code: input.denial_code,
    denial_label: {
      'PTOT08A': 'MTB Reached',
      'PTOT05': 'Non-Skilled',
      'PTOT21': 'Re-eval Bundled',
      'PTOT19': 'Dup Eval'
    }[input.denial_code] || input.denial_label || 'Unknown',
    patient_name: input.patient_name,
    member_id: input.member_id || '',
    dos: input.dos,
    denied_amount: parseFloat(input.denied_amount) || 0,
    denial_date: input.denial_date || new Date().toISOString().split('T')[0],
    plan_type: input.plan_type || 'Unknown',
    payer_name: input.payer_name || 'Unknown',
    claim_number: input.claim_number || '',
    provider: input.provider || '',
    location: input.location || '',
    cpt_codes: input.cpt_codes || [],
    npi: input.npi || '',
    entity_name_on_denial: input.entity_name || '',
    source: 'manual_fallback'
  };
}

return [{
  json: {
    source: 'manual_fallback',
    needs_classification: needsClassification,
    raw_input: needsClassification ? JSON.stringify(input) : '',
    parsed_data: parsedData
  }
}];

// Parse Gemini text classification response
const response = $input.first().json;
let text = '';

if (response.candidates && response.candidates[0]) {
  const parts = response.candidates[0].content?.parts || [];
  text = parts.map(p => p.text || '').join('');
}

text = text.trim();
if (text.startsWith('```')) text = text.split('\n').slice(1).join('\n');
if (text.endsWith('```')) text = text.slice(0, text.lastIndexOf('```'));
text = text.trim();
if (text.startsWith('json')) text = text.slice(4).trim();

let classification;
try {
  classification = JSON.parse(text);
} catch (e) {
  throw new Error(`Failed to parse Gemini response: ${e.message}. Raw: ${text.slice(0, 200)}`);
}

const c = classification.classification || {};
const entity = classification.entity || {};
const patient = classification.patient || {};
const claim = classification.claim || {};
const payer = classification.payer || {};
const provider = classification.provider || {};

const denialDate = claim.denial_date || new Date().toISOString().split('T')[0];
const deadline = new Date(denialDate);
deadline.setDate(deadline.getDate() + 365);

return [{
  json: {
    denial_code: c.denial_code || 'OTHER',
    denial_label: c.denial_label || 'Unknown',
    confidence: c.confidence || 0,
    reasoning: c.reasoning || '',
    entity_name_on_denial: entity.name_on_denial || '',
    patient_name: patient.name || 'Unknown Patient',
    member_id: patient.member_id || '',
    dos: claim.dos_start || '',
    denied_amount: parseFloat(claim.denied_amount) || 0,
    denial_date: denialDate,
    filing_deadline: deadline.toISOString().split('T')[0],
    plan_type: payer.plan_type || 'Unknown',
    payer_name: payer.name || 'Unknown',
    claim_number: claim.claim_number || '',
    provider: provider.name || '',
    npi: provider.npi || '',
    cpt_codes: claim.cpt_codes || [],
    location: '',
    missing_fields: classification.missing_fields || [],
    urgency: classification.urgency || 'standard',
    source: 'gemini_classified'
  }
}];

// Pass through pre-parsed structured data (no AI needed)
const data = $input.first().json.parsed_data;

if (!data.filing_deadline) {
  const denialDate = data.denial_date || new Date().toISOString().split('T')[0];
  const deadline = new Date(denialDate);
  deadline.setDate(deadline.getDate() + 365);
  data.filing_deadline = deadline.toISOString().split('T')[0];
}

const today = new Date();
const deadlineDate = new Date(data.filing_deadline);
const daysRemaining = Math.ceil((deadlineDate - today) / (1000 * 60 * 60 * 24));
data.urgency = daysRemaining < 30 ? 'urgent' : 'standard';
data.source = 'structured_input';

return [{ json: data }];

// ============================================================
// ENTITY LOOKUP — Match entity name from denial to master config
// ============================================================
// Entity config is loaded from n8n static data or environment.
// In production, this would reference config/entities.json via
// a separate "Read File" or pre-loaded static data.
//
// For n8n, we store entities as a JSON string in an environment
// variable (ENTITIES_CONFIG) or use the n8n static data feature.
// ============================================================

const data = $input.first().json;

// Parse entity config from environment variable
let entities = [];
try {
  const raw = $env.ENTITIES_CONFIG || '[]';
  entities = JSON.parse(raw);
} catch (e) {
  // Fallback: no entity config available
  entities = [];
}

// The entity name extracted by Gemini from the denial letter
const entityNameOnDenial = (data.entity_name_on_denial || '').trim().toLowerCase();

// Also check ERA data if coming from DrChrono path
const eraProvider = (data.era_entity_name || '').trim().toLowerCase();
const searchName = entityNameOnDenial || eraProvider;

let matchedEntity = null;

if (searchName) {
  // Tier 1: Exact match on entity_name
  matchedEntity = entities.find(e =>
    e.entity_name.toLowerCase() === searchName
  );

  // Tier 2: Match on aliases
  if (!matchedEntity) {
    matchedEntity = entities.find(e =>
      (e.aliases || []).some(a => a.toLowerCase() === searchName)
    );
  }

  // Tier 3: Fuzzy — entity name contained in search or vice versa
  if (!matchedEntity) {
    matchedEntity = entities.find(e =>
      searchName.includes(e.entity_name.toLowerCase()) ||
      e.entity_name.toLowerCase().includes(searchName)
    );
  }
}

// Build enriched data with entity information
const enriched = {
  ...data,
  // Entity fields (from config or blank for manual fill)
  entity_id: matchedEntity?.id || '',
  entity_name: matchedEntity?.entity_name || data.entity_name_on_denial || '',
  entity_npi: matchedEntity?.npi || '',
  entity_tax_id: matchedEntity?.tax_id || '',
  entity_address: matchedEntity ? `${matchedEntity.address}, ${matchedEntity.city}, ${matchedEntity.state} ${matchedEntity.zip}` : '',
  entity_phone: matchedEntity?.phone || '',
  entity_fax: matchedEntity?.fax || '',
  entity_specialty: matchedEntity?.specialty || '',
  entity_matched: !!matchedEntity,
  // Determine if this is a known payer with auto-appeal support
  payer_name: data.payer_name || 'Unknown',
  is_known_payer: (data.payer_name || '').toLowerCase().includes('optum') ||
                  (data.payer_name || '').toLowerCase().includes('unitedhealthcare') ||
                  (data.payer_name || '').toLowerCase().includes('uhc'),
  // Determine if this is a known denial code with auto-appeal support
  is_known_denial_code: ['PTOT08A', 'PTOT05', 'PTOT21', 'PTOT19'].includes(data.denial_code),
  // Can we auto-draft an appeal?
  can_auto_appeal: false  // Set below
};

// Auto-appeal only if: known payer + known denial code
enriched.can_auto_appeal = enriched.is_known_payer && enriched.is_known_denial_code;

// Determine appeal status based on what we can automate
if (enriched.can_auto_appeal) {
  enriched.initial_status = 'New';  // Will trigger auto-draft in WF2
} else {
  enriched.initial_status = 'Manual Review Required';  // Staff handles manually
}

return [{ json: enriched }];

// Check if a duplicate item already exists on the Monday.com board
// Match criteria: same patient name + same DOS + same denial code
const data = $('Entity Lookup').first().json;
const dupeResponse = $input.first().json;

const existingItems = dupeResponse?.data?.items_page_by_column_values?.items || [];
let isDuplicate = false;
let existingItemId = null;
let existingItemName = null;

for (const item of existingItems) {
  const columns = {};
  for (const col of (item.column_values || [])) {
    columns[col.id] = col.text || '';
  }

  // Check if DOS matches
  const existingDos = columns['date_mm0fp9n1'] || '';
  const existingCode = columns['dropdown_mm0ffjcd'] || '';

  const dosMatch = existingDos && data.dos && existingDos === data.dos;
  const codeMatch = existingCode && data.denial_code &&
    existingCode.toLowerCase().includes(data.denial_code.toLowerCase());

  if (dosMatch && codeMatch) {
    isDuplicate = true;
    existingItemId = item.id;
    existingItemName = item.name;
    break;
  }
}

return [{
  json: {
    ...data,
    is_duplicate: isDuplicate,
    existing_item_id: existingItemId,
    existing_item_name: existingItemName
  }
}];

// Build Monday.com item with entity data, payer info, and status
const data = $input.first().json;

const columnValues = {
  // Denial Code (dropdown)
  dropdown_mm0ffjcd: {
    labels: [data.denial_code === 'OTHER'
      ? `OTHER - ${(data.denial_label || 'Unknown').slice(0, 50)}`
      : `${data.denial_code} - ${data.denial_label}`]
  },
  // DOS (date)
  date_mm0fp9n1: { date: data.dos || '' },
  // Amount (numbers)
  numeric_mm0fh3jn: String(data.denied_amount || 0),
  // Plan Type (dropdown)
  dropdown_mm0fjy49: { labels: [data.plan_type || 'Unknown'] },
  // Denial Date
  date_mm0frn70: { date: data.denial_date || '' },
  // Filing Deadline
  date_mm0fgzne: { date: data.filing_deadline || '' },
  // Appeal Status — "New" for auto-appeal, "Manual Review Required" otherwise
  color_mm0fj7fm: { label: data.initial_status || 'New' },
  // Provider (dropdown)
  dropdown_mm0fdaya: data.provider ? { labels: [data.provider] } : {},
  // Location (dropdown)
  dropdown_mm0fac7b: data.location ? { labels: [data.location] } : {},
  // Entity Name (text) — NEW COLUMN
  text_mm0gr7ga: data.entity_name || data.entity_name_on_denial || '',
  // Entity NPI (text) — NEW COLUMN
  text_mm0gv12z: data.entity_npi || data.npi || '',
  // Payer Name (text) — NEW COLUMN
  text_mm0gw2sh: data.payer_name || ''
};

return [{
  json: {
    item_name: `${data.patient_name} — ${data.denial_code}`,
    column_values: JSON.stringify(columnValues),
    group_id: 'group_mm0fc0ne',
    ...data
  }
}];

// Prepare alert with entity, payer, and auto-appeal status info
const response = $input.first().json;
const item = response?.data?.create_item;

if (!item || !item.id) {
  throw new Error('Failed to create Monday.com item: ' + JSON.stringify(response));
}

const data = $('Build Monday.com Item').first().json;

const urgencyLabel = data.urgency === 'urgent' ? ' [URGENT]' : '';
let statusNote = '';

if (!data.is_known_payer) {
  statusNote = '\n\n** NON-OPTUM PAYER: ' + data.payer_name + ' — Auto-appeal NOT available. Manual appeal required.';
} else if (!data.is_known_denial_code) {
  statusNote = '\n\n** UNKNOWN DENIAL CODE: ' + data.denial_code + ' (' + data.denial_label + ') — Auto-appeal NOT available. Manual appeal required.';
}

if (!data.entity_matched) {
  statusNote += '\n\n** ENTITY NOT MATCHED: "' + (data.entity_name_on_denial || 'unknown') + '" not found in entity config. Please verify and update entities.json.';
}

let sourceNote = '';
if (data.source === 'gdrive_scan') {
  sourceNote = '\nSource: Scanned document (' + (data.file_name || 'unknown') + ')';
  if (data.scan_quality && data.scan_quality !== 'good') {
    sourceNote += '\nScan Quality: ' + data.scan_quality + ' — please verify extracted data';
  }
} else if (data.source === 'drchrono_era') {
  sourceNote = '\nSource: DrChrono ERA/835 (electronic)';
}

const alertMessage = `New Denial Received${urgencyLabel}\n` +
  `Entity: ${data.entity_name || 'Unknown'}\n` +
  `Patient: ${data.patient_name}\n` +
  `Payer: ${data.payer_name || 'Unknown'}\n` +
  `Code: ${data.denial_code} — ${data.denial_label}\n` +
  `Amount: $${data.denied_amount}\n` +
  `DOS: ${data.dos}\n` +
  `Filing Deadline: ${data.filing_deadline}\n` +
  `Status: ${data.initial_status}` +
  sourceNote +
  statusNote +
  `\n\nBoard: https://phw-team.monday.com/boards/18399605169`;

return [{
  json: {
    monday_item_id: item.id,
    monday_item_name: item.name,
    alert_message: alertMessage,
    ...data
  }
}];

// Handle duplicate — alert staff but do NOT create new item
const data = $input.first().json;

const alertMessage = `DUPLICATE DENIAL DETECTED\n` +
  `Patient: ${data.patient_name}\n` +
  `Code: ${data.denial_code} — ${data.denial_label}\n` +
  `DOS: ${data.dos}\n` +
  `Existing Item: ${data.existing_item_name} (ID: ${data.existing_item_id})\n` +
  `Source: ${data.source}\n\n` +
  `No new Monday.com item created. The existing item has been preserved.\n` +
  `Board: https://phw-team.monday.com/boards/18399605169`;

return [{
  json: {
    alert_message: alertMessage,
    ...data
  }
}];

// Normalize DrChrono ERA data for the shared pipeline
const data = $input.first().json;
const era = data.era_data;

return [{
  json: {
    denial_code: era.denial_code || 'OTHER',
    denial_label: era.denial_code ? ({
      'PTOT08A': 'MTB Reached',
      'PTOT05': 'Non-Skilled',
      'PTOT21': 'Re-eval Bundled',
      'PTOT19': 'Dup Eval'
    }[era.denial_code] || era.denial_code) : 'Unknown — from ERA',
    patient_name: era.patient_name || 'Unknown Patient',
    member_id: era.member_id || '',
    dos: era.dos || '',
    denied_amount: era.denied_amount || 0,
    denial_date: era.denial_date || new Date().toISOString().split('T')[0],
    plan_type: 'Unknown',
    payer_name: era.payer_name || 'Unknown',
    claim_number: era.claim_number || '',
    provider: era.provider || '',
    npi: era.npi || '',
    cpt_codes: era.cpt_codes || [],
    entity_name_on_denial: era.provider || '',
    location: '',
    missing_fields: [],
    urgency: 'standard',
    source: 'drchrono_era'
  }
}];
